contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.f{value: amount}();
        address owner = c.owner();
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }
